// ==== v1.78 PORT RAIL: E6 + D6 + C6 =====================================================================================================
// The three tracks that stopped at the E5/E6 boundary now continue into the port:
//  · Main A (x 5800, southbound) and main B (x 5900, northbound) run on to the Port Halt (island platform between the two tracks). A crossover
//    north of the platform lets a train that arrived on A reverse onto B and go back to the yard; the platform tracks end at buffer stops.
//  · GATE-75 (RAIL-02/03): the quay siding lies at y 5120, 80 px from the quay edge (y 5200), flush in the apron under the crane span
//    (landside crane rail y 5038, waterside crane rail y 5192) and runs through E6, D6 and C6 to a buffer stop in C6. Main A reaches it on a
//    R 400 arc (END-A (5800,4720) -> Q-E (5400,5120)); main B is joined from the east line by a symmetric R 400 arc (B-J (6300,5120)).
//    Roads never cross a track (every port road ends at the quay road y 4960).
function portArc(cx,cy,r,a0,a1,n=18){const pts=[];for(let i=0;i<=n;i++){const t=a0+(a1-a0)*i/n;pts.push([+(cx+r*Math.cos(t)).toFixed(3),+(cy+r*Math.sin(t)).toFixed(3)])}pts[0]=[cx+r*Math.cos(a0),cy+r*Math.sin(a0)];pts[n]=[cx+r*Math.cos(a1),cy+r*Math.sin(a1)];return pts}
