function rjxSegs(Z){return[...Z.mains.flatMap(m=>m.segs),...Z.divs].map(id=>RAIL_SEG_BY_ID[id]).filter(Boolean)}
function rjxOff(P,o){return e5OffsetPts(P,o)}
function rjxPoly(P,o){const A=rjxOff(P,-o),B=rjxOff(P,o).reverse(),Q=A.concat(B);let s=0;for(let i=0;i<Q.length;i++){const a=Q[i],b=Q[(i+1)%Q.length];s+=a[0]*b[1]-b[0]*a[1]}return s<0?Q.reverse():Q}
function rjxLine(c,P){c.beginPath();c.moveTo(P[0][0],P[0][1]);for(let i=1;i<P.length;i++)c.lineTo(P[i][0],P[i][1])}
/* the y of a polyline at x (the first crossing), or null */
function rjxYAt(P,x){for(let i=1;i<P.length;i++){const a=P[i-1],b=P[i];if((a[0]-x)*(b[0]-x)<=0&&a[0]!==b[0]){const t=(x-a[0])/(b[0]-a[0]);return a[1]+(b[1]-a[1])*t}}return null}
function rjxDist(P,x,y){let m=1e9;for(let i=1;i<P.length;i++){const a=P[i-1],b=P[i],dx=b[0]-a[0],dy=b[1]-a[1],L2=dx*dx+dy*dy||1,u=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/L2));m=Math.min(m,Math.hypot(a[0]+dx*u-x,a[1]+dy*u-y))}return m}
function rjxInter(A,B){const out=[];for(let i=1;i<A.length;i++)for(let j=1;j<B.length;j++){const a=A[i-1],b=A[i],p=B[j-1],q=B[j],rx=b[0]-a[0],ry=b[1]-a[1],sx=q[0]-p[0],sy=q[1]-p[1],d=rx*sy-ry*sx;if(Math.abs(d)<1e-9)continue;
  const t=((p[0]-a[0])*sy-(p[1]-a[1])*sx)/d,u=((p[0]-a[0])*ry-(p[1]-a[1])*rx)/d;if(t>=0&&t<=1&&u>=0&&u<=1)out.push({x:a[0]+rx*t,y:a[1]+ry*t,ha:Math.atan2(ry,rx),hb:Math.atan2(sy,sx)})}return out}
