function rjxArcPos(P,x,y){let best=1e9,pos=0,acc=0;for(let i=1;i<P.length;i++){const a=P[i-1],b=P[i],dx=b[0]-a[0],dy=b[1]-a[1],L2=dx*dx+dy*dy||1,L=Math.sqrt(L2),u=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/L2)),d=Math.hypot(a[0]+dx*u-x,a[1]+dy*u-y);if(d<best){best=d;pos=acc+u*L}acc+=L}return pos}
function rjxCut(P,cuts,g){if(!cuts.length)return[P];const cum=[0];for(let i=1;i<P.length;i++)cum.push(cum[i-1]+Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1]));const L=cum[cum.length-1],iv=[];let s=0;
 for(const c of cuts.slice().sort((x,y)=>x-y)){if(c-g>s)iv.push([s,c-g]);s=Math.max(s,c+g)}if(s<L)iv.push([s,L]);
 const at=v=>{let i=1;while(i<P.length-1&&cum[i]<v)i++;const t=(v-cum[i-1])/((cum[i]-cum[i-1])||1);return[P[i-1][0]+(P[i][0]-P[i-1][0])*t,P[i-1][1]+(P[i][1]-P[i-1][1])*t]};
 return iv.filter(([a,b])=>b-a>.5).map(([a,b])=>{const o=[at(a)];for(let i=0;i<P.length;i++)if(cum[i]>a&&cum[i]<b)o.push(P[i]);o.push(at(b));return o})}
