 c.fillStyle='#3d4246';c.beginPath();c.moveTo(x+b[0]*8,y+b[1]*8);c.lineTo(x+n[0]*2.6,y+n[1]*2.6);c.lineTo(x-b[0]*8,y-b[1]*8);c.lineTo(x-n[0]*2.6,y-n[1]*2.6);c.closePath();c.fill();
